CREATE DATABASE IF NOT EXISTS myschoool CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE myschoool;
CREATE TABLE users(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(150) NOT NULL UNIQUE,password VARCHAR(255) NOT NULL,level VARCHAR(50) NOT NULL,role ENUM('student','teacher','admin') DEFAULT 'student',subject VARCHAR(100) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE lessons(id INT AUTO_INCREMENT PRIMARY KEY,title VARCHAR(200) NOT NULL,subject VARCHAR(100) NOT NULL,level VARCHAR(50) NOT NULL,file VARCHAR(255) NOT NULL,teacher_id INT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE exams(id INT AUTO_INCREMENT PRIMARY KEY,title VARCHAR(200) NOT NULL,subject VARCHAR(100) NOT NULL,level VARCHAR(50) NOT NULL,file VARCHAR(255) NOT NULL,correction VARCHAR(255) NULL,teacher_id INT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE videos(id INT AUTO_INCREMENT PRIMARY KEY,title VARCHAR(200) NOT NULL,subject VARCHAR(100) NOT NULL,level VARCHAR(50) NOT NULL,url VARCHAR(300) NULL,video_file VARCHAR(255) NULL,teacher_id INT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS views(user_id INT NOT NULL,item_type ENUM('lesson','exam','correction','video') NOT NULL,item_id INT NOT NULL,hits INT DEFAULT 1,first_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,last_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(user_id,item_type,item_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS messages(id INT AUTO_INCREMENT PRIMARY KEY,sender_id INT NOT NULL,receiver_id INT NOT NULL,body VARCHAR(1000) NOT NULL,file VARCHAR(255) NULL,file_name VARCHAR(150) NULL,is_read TINYINT DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(receiver_id,is_read),INDEX(sender_id,receiver_id),FOREIGN KEY(sender_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(receiver_id) REFERENCES users(id) ON DELETE CASCADE);
